// 教学化摘录：packages/core/session/src/types.ts
interface SessionEvent<T extends keyof SessionEventMap = keyof SessionEventMap> {
  readonly seq: number
  readonly time: number
  readonly type: T
  readonly data: SessionEventMap[T]
  readonly surfaceOp?: SurfaceOperation
  readonly sourceEventSeqs?: readonly number[]
}

// 可运行风格示例：插件声明并追加事件
declare module '@deepseek-ai/dsh-session/types' {
  interface SessionEventMap {
    'review/state': { status: 'pending' | 'passed' | 'failed' }
  }
}

session.append('review/state', { status: 'pending' })

// 源码常量：packages/session/session-persistence/src/coordinator.ts
export const DEFAULT_PREPARED_SESSION_CACHE_SIZE = 5
export const DEFAULT_WRITE_BATCH_MAX_DELAY_MS = 200

// 教学伪代码：冷恢复流程
const snapshot = await persistence.listSnapshots()
const prepared = await persistence.prepare(id, signal)
try {
  const agent = agents.resume(prepared)
  prepared.commit()
  return agent
} finally {
  prepared[Symbol.dispose]?.()
}

// 源码裁剪
export interface ProjectionDefinition<K extends keyof SessionProjectionMap, S> {
  key: K
  schema: ZodType<SessionProjectionMap[K]>
  init(): S
  apply(state: S, event: SessionEvent): S
  view(state: S): SessionProjectionMap[K]
  stateVersion: number
}

// 教学伪代码：分页与投影组合
const snapshots = await persistence.listSnapshots(signal)
for (const { header, revision } of snapshots) {
  const projections = await projectionCache.read(header.id, revision, signal)
  yield { header, revision, projections }
}

// 源码裁剪：packages/compaction/compaction-basic/src/region.ts
let accumulated = 0
let keepFromIdx = pricedNodes.length
for (let i = pricedNodes.length - 1; i >= 0; i--) {
  accumulated += pricedNodes[i]!.tokens
  keepFromIdx = i
  if (accumulated >= retainTokens) break
}
while (keepFromIdx > 0
  && !toolPairingBalancedBefore(session, surfaceNodes[keepFromIdx]!)) {
  keepFromIdx--
}

// 教学伪代码：压缩事务结构
const startEvent = session.append('compaction/start', { id, range, owner })
try {
  const summary = await summarizer.summarize(input, signal)
  assertSurfaceStillMatches(range)
  const summaryEvent = session.append('compaction/summary', {
    compactionId: id,
    summary,
    shadowedRange: range,
    shadowedSeqs: range.shadowedSeqs,
  })
  session.append('user/message', checkpointMessage(summary), {
    surfaceOp: { op: 'replace', start: range.start, end: range.end },
    sourceEventSeqs: [startEvent.seq, summaryEvent.seq, ...range.shadowedSeqs],
  })
  session.append('compaction/end', { id, outcome: 'committed' })
} catch (error) {
  session.append('compaction/end', { id, outcome: 'failed' })
  throw error
}

// 可运行示例：命令输出保留首尾
const retained = new TextRetainer({
  kind: 'headTail', headBytes: 32_000, tailBytes: 32_000,
})
for await (const chunk of processOutput) retained.push(chunk)
const result = retained.finish()
// result.text + result.omittedBytes

// 源码裁剪：packages/compaction/compaction-tool-result-pruner/src/index.ts
session.append('compaction/prune', {
  shadowedRange: { start: seq, end: seq },
  shadowedSeqs: [seq],
  shadowedTokenCount: tokenMeter.estimateMessage(original),
})
session.append('tool/result', replacement, {
  surfaceOp: { op: 'replace', start: seq, end: seq },
  sourceEventSeqs: [seq],
})
